# Prompt: Create a function to calculate the factorial of a given number



def factorial(n):

    """Calculate the factorial of a given number n."""

    if n == 0 or n == 1:

        return 1

    else:

        return n * factorial(n - 1)



# Test the function with an example

print(factorial(5))  # Output: 120

